def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    fixed70_count = 0
    high_pressure = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = None
            if prev:
                bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)
                if abs(bid - 70) < 1e-9:
                    fixed70_count += 1
                if bid >= 90:
                    high_pressure += 1

    if not alive:
        return max(0.0, min(budget, 18.0))

    units = supply / WATER_REQ
    very_tight = units < 1.6
    tight = units < 2.1

    highest_prev = max(prev_bids) if prev_bids else 70.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

    critical = hp <= 3 or no_water_days >= 1
    fragile = hp <= 5

    if critical:
        target = max(92.0, highest_prev + 2.5)
        if budget < target:
            return max(0.0, budget)
        return max(0.0, min(budget, target))

    if very_tight:
        if high_pressure >= 2:
            target = max(96.0, second_prev + 1.5)
        else:
            target = max(72.5, highest_prev + 1.5)
        return max(0.0, min(budget, target))

    if tight:
        if fragile:
            target = max(74.0, min(98.0, highest_prev + 1.0))
        else:
            if fixed70_count >= 1:
                target = 71.5
            else:
                target = 63.0
        return max(0.0, min(budget, target))

    if hp >= 8 and budget < DAILY_SALARY * 6:
        return max(0.0, min(budget, 22.0))

    if fixed70_count >= 1 and hp >= 6:
        return max(0.0, min(budget, 71.2))

    if day >= 8 and hp >= 6:
        return max(0.0, min(budget, 58.0))

    return max(0.0, min(budget, 48.0))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents only
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append((oid, o))

    # If no opponents alive, bid enough to cover requirement
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday bids from previous_trace
    yesterday_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate how many water units we may need to outlast; supply is total water this day
    # We aim for a bid level that tends to win enough allocation share.
    # Use a conservative baseline to avoid the Alex/David failure mode.
    base_bid = DAILY_SALARY * 0.55

    # If my hp is low, increase urgency.
    if my_status['hp'] is not None and my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.9
    elif my_status['hp'] is not None and my_status['hp'] <= 4:
        base_bid = DAILY_SALARY * 0.7

    # React to yesterday's most aggressive opponent
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If someone bid near our daily salary, they likely were fighting for survival.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If we are healthy, still bid to secure share; if not, bid very high.
            if my_status.get('hp', 0) > 3:
                target = DAILY_SALARY * 0.65
            else:
                target = DAILY_SALARY * 0.95
        else:
            # Keep slightly above baseline and scale with observed aggressiveness
            target = max(base_bid, highest_prev_bid + 5.0)
    else:
        target = base_bid

    # Adjust for supply level: lower supply means more competition, bid a bit higher.
    # supply in [15,25]
    if supply <= 18.0:
        target *= 1.15
    elif supply >= 22.0:
        target *= 0.95

    # Budget safety: never bid more than what we can afford comfortably.
    budget = float(my_status.get('budget', 0.0))
    if budget <= 0.0:
        return 0.0

    # If we are close to running out of budget, cap bid to preserve future days.
    # Use remaining no_water_days as a proxy for urgency.
    no_water_days = int(my_status.get('no_water_days', 0))
    if no_water_days >= 3:
        # Need water soon
        cap = DAILY_SALARY * 0.95
    else:
        cap = DAILY_SALARY * 0.7

    bid = min(budget, min(cap, target))

    # Ensure bid is non-negative and not absurdly high
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 # From meta-round state

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid low to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Calculate days remaining
    remaining_days = EPISODE_DAYS - day_context['day']

    # Determine if desperate for water
    is_desperate = my_status['hp'] <= 2 or my_status['no_water_days'] >= 1

    yesterday_bids = []
    eric_bid_yesterday = None

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
            if opp['agent_id'] == "Eric":
                eric_bid_yesterday = prev['bid']

    # --- Bidding Logic ---
    bid_amount = DAILY_SALARY * 0.7 # Default moderate bid

    if is_desperate:
        bid_amount = DAILY_SALARY * 0.98 # Bid very high to ensure water
    elif yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents were very aggressive yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 3 and remaining_days > EPISODE_DAYS / 2: # Early/mid-game, good HP
                bid_amount = DAILY_SALARY * 0.4 # Back off, save budget
            else:
                bid_amount = max(DAILY_SALARY * 0.75, highest_prev_bid + 5.0) # Compete, but not blindly overpay
        # If opponents were moderately aggressive
        else:
            # If Eric was the highest bidder and his bid was low (around his salary)
            # Eric's salary is likely 70, so < 90 is his range
            if eric_bid_yesterday is not None and highest_prev_bid == eric_bid_yesterday and highest_prev_bid < DAILY_SALARY * 0.6:
                bid_amount = eric_bid_yesterday + 5.0 # Just beat Eric
            else:
                # Try to slightly outbid the highest moderate bid
                bid_amount = max(DAILY_SALARY * 0.6, highest_prev_bid + 5.0)
    else:
        # Day 1 or no relevant previous bids
        if is_desperate:
            bid_amount = DAILY_SALARY * 0.95
        else:
            # On Day 1, or if previous bids are unavailable, start with a moderate bid.
            # If Eric is the only one, we can target him specifically.
            eric_is_alive = any(o['agent_id'] == "Eric" for o in alive_opponents)
            if eric_is_alive and len(alive_opponents) == 1:
                 bid_amount = 75.0 # Just beat Eric's likely 70
            else:
                 bid_amount = DAILY_SALARY * 0.7 # General moderate bid

    # Ensure bid does not exceed available budget
    return min(my_status['budget'], bid_amount)
